package audience

import (
	"fmt"
	"net/http"
	"strings"

	"github.com/Azure/azure-sdk-for-go/sdk/azcore/policy"
)

const aadAudienceErrorCode = "AADSTS500011"

type AudienceErrorHandlingPolicy struct {
	AudienceConfigured bool
}

func NewAudienceErrorHandlingPolicy(audienceConfigured bool) *AudienceErrorHandlingPolicy {
	return &AudienceErrorHandlingPolicy{
		AudienceConfigured: audienceConfigured,
	}
}

func (p *AudienceErrorHandlingPolicy) Do(req *policy.Request) (*http.Response, error) {
	resp, err := req.Next()
	if err != nil {
		if strings.Contains(err.Error(), aadAudienceErrorCode) {
			if p.AudienceConfigured {
				return nil, fmt.Errorf("unable to authenticate to Azure App Configuration. An incorrect token audience was provided. Please set ClientOptions.Cloud for the target cloud . For details on how to configure the authentication token audience visit https://aka.ms/appconfig/client-token-audience. %w", err)
			} else {
				return nil, fmt.Errorf("unable to authenticate to Azure App Configuration. No authentication token audience was provided. Please set ClientOptions.Cloud for the target cloud. For details on how to configure the authentication token audience visit https://aka.ms/appconfig/client-token-audience. %w", err)
			}
		}
		return nil, err
	}

	return resp, nil
}

